pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t1, uint256 t2) public {
        t1 = bound(t1, 2, type(uint256).max / 2);
        t2 = bound(t2, 1, t1 - 1);
        // make block.number % 15 != 0 to keep the scenario deterministic
        vm.roll(block.number - (block.number % 15) + 1);

        address actor = address(0xBEEF);
        vm.deal(actor, 20 ether);

        // first call at t1: passes the time check in both P and M
        vm.prank(actor);
        try c.fallback{value: 10 ether}() {} catch {}

        // second call at t2 < t1: reference must revert (timestamp not newer)
        vm.roll(block.number - (block.number % 15) + 1); // keep %15 != 0
        vm.warp(t2);
        vm.prank(actor);
        bool ok;
        try c.fallback{value: 10 ether}() { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}

