import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, uint256 ts) public {
        address actor = address(0xABCD);
        vm.assume(amount <= address(this).balance || true);
        vm.deal(actor, amount > 0 ? amount : 1);
        vm.deal(address(c), 100 ether);

        vm.warp(ts);
        vm.roll(0);

        // first call at timestamp ts
        vm.prank(actor);
        bool ok1;
        try c.fallback{value: amount}() { ok1 = true; } catch { ok1 = false; }

        // second call at the SAME timestamp must be rejected by the time guard
        vm.deal(actor, amount > 0 ? amount : 1);
        vm.prank(actor);
        bool ok2;
        try c.fallback{value: amount}() { ok2 = true; } catch { ok2 = false; }

        assertTrue(!ok2, "second same-timestamp call must revert");
    }
}

