pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        blockNum = bound(blockNum, 1, type(uint32).max);

        vm.roll(blockNum);
        vm.warp(blockNum * 1000 + 1); // distinct, > pastBlockTime

        uint256 balBefore = address(c).balance;
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // General rule: payout happens exactly when blockNum % 15 == 0
        if (blockNum % 15 == 0) {
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(address(c).balance == balBefore);
        }
    }
}

