pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, uint256 bn, address actor) public {
        // keep params in the admissible domain, but wide
        ts = bound(ts, 1, type(uint64).max);
        bn = bound(bn, 0, type(uint64).max);
        vm.assume(actor != address(c) && actor != address(0));

        vm.warp(ts);
        vm.roll(bn);

        // first successful call: pastBlockTime == 0 < ts, value fixed at 10 ether
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok); // guard: call must succeed in both versions

        // General rule: after the call, balance is 10 ether on a non-payout block
        // and exactly 0 on a payout block (block.number % 15 == 0), since the
        // contract pays out its entire balance to msg.sender.
        if (block.number % 15 == 0) {
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(address(c).balance == 10 ether);
        }
    }
}

