// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 b1, uint256 b2, address actor) public {
        // Admissible domain: a warm-up block with NO payout, then a payout-eligible block.
        b1 = bound(b1, 0, 1_000_000);
        b2 = bound(b2, 0, 1_000_000);
        vm.assume(b1 % 15 != 0);
        vm.assume(b2 % 15 == 0);
        vm.assume(actor != address(c));

        // History step: a valid call on a non-payout block (reference keeps balance, mutant keeps balance).
        vm.roll(b1);
        vm.warp(b1 + 1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // Deciding step: a valid call on a payout-eligible block.
        // Universal rule: no matter the preceding history, such a call drains the whole balance to 0.
        vm.roll(b2);
        vm.warp(b2 + 1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        assertTrue(address(c).balance == 0);
    }
}
